using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using V15Voice;
public static class AiRealTests {
 static int n;static void Check(bool b,string name){if(!b)throw new Exception(name);n++;Console.WriteLine("PASS "+name);}sealed class Voice:KokoroEngine {public override void CheckFiles(){}public override Wave Generate(string text,double speed,string output){int words=System.Text.RegularExpressions.Regex.Matches(text,@"\b\w+\b").Count;int length=(int)(words*.3/speed*24000);return new Wave{Rate=24000,Samples=Enumerable.Range(0,length).Select(i=>i<length-1200?(short)(5000*Math.Sin(i*.05)):(short)0).ToArray()};}}
 public static void Main(string[] args){string root=args[0],folder=Path.Combine(Path.GetTempPath(),"V15 real AI "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var cues=Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:03,300\nJohn was standing there for a very long time because the door had finally opened.\n");string input=Path.Combine(folder,"story.srt");File.WriteAllText(input,Scripts.ToSrt(cues));var settings=new VoiceSettings{Mode=0,Key="fixture",Device="cpu",Breathing=2,Normalize=false,Slow=false};var p=AiRepairSession.Open(input,cues,folder,settings,false,"fixture voice, real language model");var ai=new LocalAi(root,"cpu");var timer=Stopwatch.StartNew();AiTimeline.Run(p,ai,role=>new Voice{Root=root,VoiceName="Measured test voice",Archive=new SpeechArchive(folder)},()=>false,(i,m)=>Console.WriteLine(i+" "+m),false);Check(p.Rows[0].Attempts.Count>0&&p.Rows[0].Attempts.All(a=>a.Raw.Length>0),"Actual GGUF model executes through C# subprocess integration");foreach(var a in p.Rows[0].Attempts)Console.WriteLine("ATTEMPT "+a.Number+" "+a.Raw+" error="+a.Error+" result="+(a.Measurement==null?"none":a.Measurement.Detail));Check(p.Rows[0].Best!=null,"Real Qwen proposal passes structural/fact guards and measured timeline test");Check(p.Rows[0].Accepted==0&&p.Effective()[0].Text==cues[0].Text,"Real AI proposal remains pending user approval");Check(ai.LastDevice.StartsWith("CPU")&&File.ReadAllText(p.Report).Contains("CPU · đã hoàn tất suy luận"),"Runtime device report reflects completed CPU inference");Check(File.ReadAllText(input)==Scripts.ToSrt(cues),"Real rewrite never mutates source SRT");Console.WriteLine("TOTAL REAL AI "+n+" passed in "+timer.Elapsed.TotalSeconds.ToString("0.0")+"s (actual 4B model, synthetic voice timing; not a semantic quality score). "+folder);}
}
